                column: "StepsData",
                value: "[\n  {\n    \"number\": 1,\n    \"title\": \"Reactants\",\n    \"description\": \"Iron (Fe) is a solid metal on the left. Two hydrochloric acid (HCl) molecules sit on the right \\u2014 each is a hydrogen atom covalently bonded to a chlorine atom. The reactants are not yet in contact.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": -4,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": 2.5,\n        \"y\": 1.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl1\",\n        \"element\": \"Cl\",\n        \"x\": 3.3,\n        \"y\": 1.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n        \"x\": 2.5,\n        \"y\": -1.5,\n        \"z\": 0\n      },\n      {\n        \"id\": \"cl2\",\n        \"element\": \"Cl\",\n        \"x\": 3.3,\n        \"y\": -1.5,\n        \"z\": 0\n      }\n    ],\n    \"bonds\": [\n      {\n        \"from\": \"h1\",\n        \"to\": \"cl1\"\n      },\n      {\n        \"from\": \"h2\",\n        \"to\": \"cl2\"\n      }\n    ],\n    \"electronTransfers\": [],\n    \"atomOverrides\": {}\n  },\n  {\n    \"number\": 2,\n    \"title\": \"Acid Dissociation\",\n    \"description\": \"Hydrochloric acid dissociates into H\\u207A and Cl\\u207B ions. The ions surround the iron surface \\u2014 the H\\u2013Cl covalent bonds are broken. Chloride ions are attracted to the positive iron surface; protons hover nearby, ready to accept electrons.\",\n    \"background\": \"default\",\n    \"atoms\": [\n      {\n        \"id\": \"fe1\",\n        \"element\": \"Fe\",\n        \"x\": 0,\n        \"y\": 0,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h1\",\n        \"element\": \"H\",\n        \"x\": -1.8,\n        \"y\": 1,\n        \"z\": 0\n      },\n      {\n        \"id\": \"h2\",\n        \"element\": \"H\",\n 